module logic;
use model {Entry,Summary};
use util {reverse};
record Cursor {pending:List<Entry>,kept:List<Entry>}
record KeyScan {pending:List<Entry>,found:Bool}
record ActiveCursor {pending:List<Entry>,output:List<Entry>}
fn hasKey(entries:List<Entry>,key:I64)->Bool {
 let final=fold(i in List::length(entries),state:KeyScan=KeyScan {pending:entries,found:false}) {
  let item=List::head(state.pending);
  KeyScan {pending:List::tail(state.pending),found:state.found || item.key==key}
 };final.found
}
fn activeOnly(entries:List<Entry>)->List<Entry> {
 let final=fold(i in List::length(entries),state:ActiveCursor=ActiveCursor {pending:entries,output:List::empty<Entry>()}) {
  let item=List::head(state.pending);
  ActiveCursor {pending:List::tail(state.pending),output:if item.active {List::prepend(item,state.output)} else {state.output}}
 };reverse(final.output)
}
fn run(entries:List<Entry>)->Summary {
 let final=fold(i in List::length(entries),cursor:Cursor=Cursor {pending:reverse(entries),kept:List::empty<Entry>()}) {
  let item=List::head(cursor.pending);
  Cursor {pending:List::tail(cursor.pending),kept:if hasKey(cursor.kept,item.key) {cursor.kept} else {List::prepend(item,cursor.kept)}}
 };
 let kept=activeOnly(final.kept);
 Summary {kept:kept,dropped:List::length(entries)-List::length(kept)}
}

